func TestSaveRecordingLifecycle(t *testing.T) {
	ctx := context.Background()
	s := newStore(t)

	id, st, err := s.SaveRecording(ctx, recording("fit:1:1:1", "aaa", 1))
	if err != nil || st != Created {
		t.Fatalf("first save: %v %v", st, err)
	}

	// Same file again → no write at all.
	id2, st, err := s.SaveRecording(ctx, recording("fit:1:1:1", "aaa", 1))
	if err != nil || st != Unchanged || id2 != id {
		t.Fatalf("re-import: id=%d status=%v err=%v", id2, st, err)
	}

	// Changed content (re-saved file) or newer pipeline → update in place.
	changed := recording("fit:1:1:1", "bbb", 1)
	changed.Activity.DistanceM = 43000
	if id3, st, err := s.SaveRecording(ctx, changed); err != nil || st != Updated || id3 != id {
		t.Fatalf("changed file: id=%d status=%v err=%v", id3, st, err)
	}
	if _, st, _ := s.SaveRecording(ctx, recording("fit:1:1:1", "bbb", 2)); st != Updated {
		t.Errorf("newer analysis version: status %v", st)
	}

	n, _ := s.Count(ctx)
	if n != 1 {
		t.Errorf("count %d, want 1", n)
	}
	a, err := s.Get(ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	if a.AnalysisVersion != 2 || a.DistanceM != 42000 {
		t.Errorf("after updates: version=%d distance=%v", a.AnalysisVersion, a.DistanceM)
	}
}

