func TestRoundTripOfActivityFields(t *testing.T) {
	ctx := context.Background()
	s := newStore(t)
	rec := recording("fit:1:1:1", "aaa", 1)
	id, _, err := s.SaveRecording(ctx, rec)
	if err != nil {
		t.Fatal(err)
	}
	got, err := s.Get(ctx, id)
	if err != nil {
		t.Fatal(err)
	}
	want := rec.Activity
	want.ID, want.CreatedAt, want.UpdatedAt = got.ID, got.CreatedAt, got.UpdatedAt
	if *got.BBox != *want.BBox {
		t.Errorf("bbox %+v", got.BBox)
	}
	got.BBox, want.BBox = nil, nil
	if got != want {
		t.Errorf("round trip\n got %+v\nwant %+v", got, want)
	}
	if got.LocalStart().Hour() != 10 {
		t.Errorf("local start %v", got.LocalStart())
	}

	stream, err := s.Stream(ctx, id)
	if err != nil || stream.Encoding != "json+gzip;v1" || len(stream.Data) != 3 {
		t.Errorf("stream %+v %v", stream, err)
	}
	track, err := s.Track(ctx, id)
	if err != nil || track.Points != 2 {
		t.Errorf("track %+v %v", track, err)
	}
}

