func TestListOrderAndFilter(t *testing.T) {
	ctx := context.Background()
	s := newStore(t)
	for i, sport := range []string{"cycling", "hiking", "cycling"} {
		rec := recording("fit:1:1:"+string(rune('a'+i)), "x", 1)
		rec.Activity.Sport = sport
		rec.Activity.StartTime = rec.Activity.StartTime.Add(time.Duration(i) * 24 * time.Hour)
		if _, _, err := s.SaveRecording(ctx, rec); err != nil {
			t.Fatal(err)
		}
	}
	all, err := s.List(ctx, ListFilter{})
	if err != nil || len(all) != 3 || !all[0].StartTime.After(all[1].StartTime) {
		t.Fatalf("list: %d %v", len(all), err)
	}
	cycling, _ := s.List(ctx, ListFilter{Sport: "cycling", Limit: 1})
	if len(cycling) != 1 || cycling[0].Sport != "cycling" {
		t.Errorf("filtered: %+v", cycling)
	}
}

